/* Program Plugin */
export type ThalerDnsPluginRequirements = ClientWithRpc<GetAccountInfoApi & GetMultipleAccountsApi> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function thalerDnsProgram() {
  const __client = new ThalerDnsClient();
  return <T extends ThalerDnsPluginRequirements>(client: T) => ({
    ...client,
    thalerDns: {
      accounts: {
        mirrorVenue: addSelfFetchFunctions(client, MirrorVenueCodec),
        mixerPool: addSelfFetchFunctions(client, MixerPoolCodec),
        redeemRequest: addSelfFetchFunctions(client, RedeemRequestCodec),
        stakeGroup: addSelfFetchFunctions(client, StakeGroupCodec),
        stakeRequest: addSelfFetchFunctions(client, StakeRequestCodec),
        vault: addSelfFetchFunctions(client, VaultCodec),
        vaultClaim: addSelfFetchFunctions(client, VaultClaimCodec),
      },
      instructions: {
        initializeMixer: (input: InitializeMixerInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createInitializeMixerInstruction(input)),
        mintTdns: (input: MintTdnsInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createMintTdnsInstruction(input)),
        burnTdns: (input: BurnTdnsInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createBurnTdnsInstruction(input)),
        registerVault: (input: RegisterVaultInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createRegisterVaultInstruction(input)),
        creditBuffer: (input: CreditBufferInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createCreditBufferInstruction(input)),
        debitBuffer: (input: DebitBufferInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createDebitBufferInstruction(input)),
        initializeVault: (input: InitializeVaultInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createInitializeVaultInstruction(input)),
        setPhoenixTrader: (input: SetPhoenixTraderInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createSetPhoenixTraderInstruction(input)),
        depositCollateral: (input: DepositCollateralInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createDepositCollateralInstruction(input)),
        withdrawCollateral: (input: WithdrawCollateralInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createWithdrawCollateralInstruction(input)),
        placePerpOrder: (input: PlacePerpOrderInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createPlacePerpOrderInstruction(input)),
        readMargin: (input: ReadMarginInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createReadMarginInstruction(input)),
        readSpotLegs: (input: ReadSpotLegsInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createReadSpotLegsInstruction(input)),
        readMarks: (input: ReadMarksInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createReadMarksInstruction(input)),
        priceGroup: (input: PriceGroupInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createPriceGroupInstruction(input)),
        checkHedge: (input: CheckHedgeInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createCheckHedgeInstruction(input)),
        resizeForDividend: (input: ResizeForDividendInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createResizeForDividendInstruction(input)),
        redeem: (input: RedeemInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createRedeemInstruction(input)),
        requestStake: (input: RequestStakeInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createRequestStakeInstruction(input)),
        settleStake: (input: SettleStakeInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createSettleStakeInstruction(input)),
        abortStake: (input: AbortStakeInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createAbortStakeInstruction(input)),
        settleGroup: (input: SettleGroupInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createSettleGroupInstruction(input)),
        requestRedeem: (input: RequestRedeemInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createRequestRedeemInstruction(input)),
        settleRedeem: (input: SettleRedeemInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createSettleRedeemInstruction(input)),
        setBackupPool: (input: SetBackupPoolInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createSetBackupPoolInstruction(input)),
        fundVault: (input: FundVaultInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createFundVaultInstruction(input)),
        initMirror: (input: InitMirrorInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createInitMirrorInstruction(input)),
        mirrorReads: (input: MirrorReadsInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createMirrorReadsInstruction(input)),
        mirrorExecuteLeg: (input: MirrorExecuteLegInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createMirrorExecuteLegInstruction(input)),
        mirrorUnwind: (input: MirrorUnwindInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createMirrorUnwindInstruction(input)),
        mirrorResize: (input: MirrorResizeInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createMirrorResizeInstruction(input)),
        mirrorDeployUndeployed: (input: MirrorDeployUndeployedInstructionInput) => addSelfPlanAndSendFunctions(client, __client.createMirrorDeployUndeployedInstruction(input)),
      },
    },
  });
}

/* PDA Helpers */
export async function findMixerAddress(): Promise<Address> {
  return (await getProgramDerivedAddress({
    programAddress: PROGRAM_ADDRESS,
    seeds: [
        new Uint8Array([109, 105, 120, 101, 114]),
    ],
  }))[0];
}

export async function findClaimAddress(mixer: Address, vault: Address): Promise<Address> {
  return (await getProgramDerivedAddress({
    programAddress: PROGRAM_ADDRESS,
    seeds: [
        new Uint8Array([99, 108, 97, 105, 109]),
      getAddressCodec().encode(mixer),
      getAddressCodec().encode(vault),
    ],
  }))[0];
}

